;(function (root) {
'use strict'

const SS = (root.SimpleSearch = root.SimpleSearch || {})

const KEY = 'ss.history'
const MAX = 10

function createMemoryStorage() {
const map = new Map()
return {
getItem(key) {
return map.has(key) ? map.get(key) : null
},
setItem(key, value) {
map.set(key, String(value))
},
removeItem(key) {
map.delete(key)
},
}
}

function isUsableStorage(storage) {
return Boolean(storage) &&
typeof storage.getItem === 'function' &&
typeof storage.setItem === 'function'
}

function normalize(raw) {
if (typeof raw !== 'string') return ''
return raw.trim().replace(/\s+/g, ' ')
}

function read(storage) {
let raw = null
try {
raw = storage.getItem(KEY)
} catch (e) {
return []
}
if (typeof raw !== 'string' || raw === '') return []

let parsed = null
try {
parsed = JSON.parse(raw)
} catch (e) {
return []
}
if (!Array.isArray(parsed)) return []

const seen = new Set()
const result = []
for (const value of parsed) {
const term = normalize(value)
if (term === '' || seen.has(term)) continue
seen.add(term)
result.push(term)
if (result.length >= MAX) break
}
return result
}

function write(storage, list) {
try {
storage.setItem(KEY, JSON.stringify(list))
} catch (e) {

}
}

function create(storage) {
const target = isUsableStorage(storage) ? storage : createMemoryStorage()

function list() {
return read(target)
}

function add(raw) {
const term = normalize(raw)
if (term === '') return list()
const next = list().filter((item) => item !== term)
next.unshift(term)
const trimmed = next.slice(0, MAX)
write(target, trimmed)
return trimmed
}

function remove(raw) {
const term = normalize(raw)
if (term === '') return list()
const next = list().filter((item) => item !== term)
write(target, next)
return next
}

function clear() {
if (typeof target.removeItem === 'function') {
try {
target.removeItem(KEY)
return
} catch (e) {

}
}
write(target, [])
}

return { list, add, remove, clear }
}

let cachedInstance = null
let memoryStorage = null

function getInstance() {
if (cachedInstance) return cachedInstance
let storage = null
try {
const candidate = root.localStorage
if (isUsableStorage(candidate)) storage = candidate
} catch (e) {
storage = null
}
if (!storage) {
if (!memoryStorage) memoryStorage = createMemoryStorage()
storage = memoryStorage
}
cachedInstance = create(storage)
return cachedInstance
}

SS.history = {
KEY,
MAX,
create,
record(raw) {
return getInstance().add(raw)
},
list() {
return getInstance().list()
},
remove(raw) {
return getInstance().remove(raw)
},
clear() {
getInstance().clear()
},
}
})(typeof globalThis !== 'undefined' ? globalThis : this)
